import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Form Proposal: Queue","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/queue.md","filePath":"proposals/queue.md"}'),i={name:"proposals/queue.md"};function s(n,e,d,c,l,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="form-proposal-queue" tabindex="-1">Form Proposal: Queue <a class="header-anchor" href="#form-proposal-queue" aria-label="Permalink to &quot;Form Proposal: Queue&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>The candidate Form describes durable message queues for connected producers and consumers: queue lifecycle, narrow delivery intent, retention constraints, and messaging capability. Broker choice, consumer materialization, batching, retries, visibility leases, delivery delay, credentials, placement, capacity, and price remain host-owned.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>At-least-once delivery, retention, and ordering are observable semantics that can be exercised against multiple brokers. Consumer batch size, retry count, visibility timeout, delivery delay, maximum message size, broker binding, and dead-letter policy are excluded because they couple producer lifecycle to host or consumer operation.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Delivery or retention changes may require a new queue and drain. Delete or migration can discard messages. Import requires exact broker identity and delivery evidence. Message bodies, consumer code, and credentials never enter portable Resource state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI Resource/Link/Action, TOSCA messaging relationships, Kubernetes broker operators/KEDA, Crossplane resources, and Terraform SQS/PubSub/Service Bus/ Cloudflare Queue resources are applicable; CIMI has no focused queue contract. The gap is a deliberately narrow broker-neutral lifecycle and connection model.</p>',10)])])}const b=a(i,[["render",s]]);export{m as __pageData,b as default};
